<script>
(function(){
 const button=document.getElementById('saveA00PdfButton'); if(!button)return;
 button.addEventListener('click',async function(){
  const original=button.textContent; button.disabled=true;
  try{
   let handle=null;
   if(window.showSaveFilePicker){handle=await window.showSaveFilePicker({suggestedName:button.dataset.filename,types:[{description:'Dokumen PDF',accept:{'application/pdf':['.pdf']}}]});}
   button.textContent='Menyiapkan PDF...';
   const response=await fetch(button.dataset.url,{headers:{Accept:'application/pdf'}}); if(!response.ok)throw new Error('PDF gagal dibuat.');
   const blob=await response.blob();
   if(handle){const writable=await handle.createWritable();await writable.write(blob);await writable.close();}
   else{const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=button.dataset.filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
   button.textContent='Tersimpan'; setTimeout(()=>button.textContent=original,1500);
  }catch(error){if(error&&error.name!=='AbortError')openAppNotify(error.message||'PDF gagal disimpan.');button.textContent=original;}
  finally{button.disabled=false;}
 });
})();
</script>
